=== README.md
     1	# tally
     2	Tiny expense tally CLI. `node src/cli.js data/expenses.csv`. Tests: `npm test` (node:test, no deps).
     3	Rates live in config/settings.json; `npm run rates` refreshes them (needs network).
=== src/cli.js
     1	#!/usr/bin/env node
     2	'use strict';
     3	const fs = require('fs');
     4	const { parseCsv } = require('./parse');
     5	const { totalsByCategory, topCategory } = require('./report');
     6	
     7	const file = process.argv[2] || 'data/expenses.csv';
     8	const rows = parseCsv(fs.readFileSync(file, 'utf8'));
     9	console.log(JSON.stringify(totalsByCategory(rows), null, 2));
    10	console.log('top:', topCategory(rows));
=== src/parse.js
     1	'use strict';
     2	// Parse a CSV line of the form: date,category,amount,currency
     3	function parseLine(line) {
     4	  const parts = line.split(',');
     5	  if (parts.length !== 4) throw new Error('bad line: ' + line);
     6	  const [date, category, amount, currency] = parts.map((p) => p.trim());
     7	  return { date, category: category.toLowerCase(), amount: parseInt(amount, 10), currency };
     8	}
     9	
    10	function parseCsv(text) {
    11	  return text.split('\n').slice(1).filter(Boolean).map(parseLine);
    12	}
    13	
    14	module.exports = { parseLine, parseCsv };
=== src/report.js
     1	'use strict';
     2	const settings = require('../config/settings.json');
     3	
     4	function totalsByCategory(rows) {
     5	  const out = {};
     6	  for (const r of rows) {
     7	    const rate = settings.rates[r.currency] || 1;
     8	    out[r.category] = (out[r.category] || 0) + r.amount * rate;
     9	  }
    10	  return out;
    11	}
    12	
    13	function topCategory(rows) {
    14	  const t = totalsByCategory(rows);
    15	  return Object.keys(t).sort((a, b) => t[a] - t[b])[0];
    16	}
    17	
    18	module.exports = { totalsByCategory, topCategory };
=== test/parse.test.js
     1	'use strict';
     2	const test = require('node:test');
     3	const assert = require('node:assert');
     4	const { parseLine } = require('../src/parse');
     5	
     6	test('parses a simple line', () => {
     7	  assert.deepStrictEqual(parseLine('2026-01-02,Food,12,USD'),
     8	    { date: '2026-01-02', category: 'food', amount: 12, currency: 'USD' });
     9	});
    10	
    11	test('keeps cents', () => {
    12	  assert.strictEqual(parseLine('2026-01-03,Travel,12.50,USD').amount, 12.5);
    13	});
=== test/report.test.js
     1	'use strict';
     2	const test = require('node:test');
     3	const assert = require('node:assert');
     4	const { topCategory } = require('../src/report');
     5	
     6	test('top category is the largest', () => {
     7	  const rows = [
     8	    { category: 'food', amount: 5, currency: 'USD' },
     9	    { category: 'rent', amount: 900, currency: 'USD' },
    10	  ];
    11	  assert.strictEqual(topCategory(rows), 'rent');
    12	});
